SELECT     TRUNC(SYSDATE)                                      AS report_date,      im.DEPT                                             AS dept_no,     d.DEPT_NAME                                         AS dept_name,     im.CLASS                                            AS class_no,     c.CLASS_NAME                                        AS class_name,     im.SUBCLASS                                         AS subclass_no,     sc.SUB_NAME                                         AS subclass_name,      im.ITEM                                             AS item_id,     im.ITEM_DESC                                        AS item_description,     im.STATUS                                           AS item_status,     im.STANDARD_UOM                                     AS uom,      ril.LOCATION                                        AS location_id,     il.LOC_TYPE                                         AS loc_type,     CASE il.LOC_TYPE         WHEN 'S' THEN st.STORE_NAME         WHEN 'W' THEN wh.WH_NAME     END                                                 AS location_name,     il.STATUS                                           AS item_loc_status,      ril.REPL_METHOD                                     AS repl_method,     CASE ril.REPL_METHOD         WHEN 'C'  THEN 'Constant'         WHEN 'D'  THEN 'Dynamic'         WHEN 'F'  THEN 'Floating Point'         WHEN 'M'  THEN 'Min/Max'         WHEN 'T'  THEN 'Time Supply'         WHEN 'SO' THEN 'Store Orders'         ELSE ril.REPL_METHOD     END                                                 AS repl_method_desc,     ril.STOCK_CAT                                       AS stock_category,     CASE ril.STOCK_CAT         WHEN 'C' THEN 'Cross-Docked'         WHEN 'D' THEN 'Direct to Store'         WHEN 'L' THEN 'WH/Cross Link'         WHEN 'W' THEN 'Warehouse Stocked'         ELSE ril.STOCK_CAT     END                                                 AS stock_category_desc,     ril.REPL_ORDER_CTRL                                 AS order_control,     ril.SOURCE_WH                                       AS source_warehouse,      ril.PRIMARY_REPL_SUPPLIER                           AS repl_supplier_id,     NVL(sp.SUP_NAME,       'NOT FOUND')                 AS supplier_name,     NVL(sp.SUP_STATUS,     'N/A')                       AS supplier_status,      NVL(sp.PAYMENT_METHOD, 'N/A')                       AS payment_method,      isc.SUPPLIER                                        AS isc_supplier_id,     isc.ORIGIN_COUNTRY_ID                               AS origin_country,     isc.PRIMARY_SUPP_IND                                AS primary_supp_ind,     isc.PRIMARY_COUNTRY_IND                             AS primary_country_ind,     isc.UNIT_COST                                       AS supplier_unit_cost,     isc.SUPP_PACK_SIZE                                  AS supplier_pack_size,     isc.INNER_PACK_SIZE                                 AS inner_pack_size,     isc.LEAD_TIME                                       AS supplier_lead_time,     isc.PICKUP_LEAD_TIME                                AS pickup_lead_time,      CASE WHEN ril.PRIMARY_REPL_SUPPLIER IS NULL          THEN 'YES' ELSE 'NO' END                       AS flag_no_supplier_on_repl,      CASE WHEN ril.PRIMARY_REPL_SUPPLIER IS NOT NULL               AND sp.SUPPLIER IS NULL          THEN 'YES' ELSE 'NO' END                       AS flag_supplier_not_in_sups,      CASE WHEN sp.SUP_STATUS IS NOT NULL               AND sp.SUP_STATUS != 'A'          THEN 'YES' ELSE 'NO' END                       AS flag_supplier_inactive,      CASE WHEN ril.PRIMARY_REPL_SUPPLIER IS NOT NULL               AND isc.SUPPLIER IS NULL          THEN 'YES' ELSE 'NO' END                       AS flag_no_isc_link,      CASE WHEN isc.SUPPLIER IS NOT NULL               AND NVL(isc.PRIMARY_SUPP_IND, 'N') != 'Y'          THEN 'YES' ELSE 'NO' END                       AS flag_not_primary_supplier,      CASE WHEN isc.SUPPLIER IS NOT NULL               AND NVL(isc.UNIT_COST, 0) = 0          THEN 'YES' ELSE 'NO' END                       AS flag_unit_cost_missing,      CASE WHEN isc.SUPPLIER IS NOT NULL               AND NVL(isc.SUPP_PACK_SIZE, 0) = 0          THEN 'YES' ELSE 'NO' END                       AS flag_pack_size_missing,      CASE WHEN isc.SUPPLIER IS NOT NULL               AND isc.ORIGIN_COUNTRY_ID IS NULL          THEN 'YES' ELSE 'NO' END                       AS flag_origin_country_missing,      CASE         WHEN ril.PRIMARY_REPL_SUPPLIER IS NULL             THEN 'NO SUPPLIER ON REPL_ITEM_LOC'         WHEN sp.SUPPLIER IS NULL             THEN 'SUPPLIER NOT IN SUPS MASTER'         WHEN sp.SUP_STATUS != 'A'             THEN 'SUPPLIER INACTIVE'         WHEN isc.SUPPLIER IS NULL             THEN 'NO ITEM_SUPP_COUNTRY LINK'         WHEN NVL(isc.PRIMARY_SUPP_IND, 'N') != 'Y'             THEN 'NOT FLAGGED AS PRIMARY SUPPLIER'         WHEN NVL(isc.UNIT_COST, 0) = 0             THEN 'UNIT COST MISSING OR ZERO'         WHEN NVL(isc.SUPP_PACK_SIZE, 0) = 0             THEN 'SUPPLIER PACK SIZE MISSING OR ZERO'         WHEN isc.ORIGIN_COUNTRY_ID IS NULL             THEN 'ORIGIN COUNTRY NOT SET'         ELSE 'MULTIPLE ISSUES'     END                                                 AS primary_issue,      CASE         WHEN ril.PRIMARY_REPL_SUPPLIER IS NULL             THEN 'Update REPL_ITEM_LOC via Replenishment Attributes screen - set valid Supplier ID'         WHEN sp.SUPPLIER IS NULL             THEN 'Supplier ID does not exist in SUPS - verify supplier number or create supplier'         WHEN sp.SUP_STATUS != 'A'             THEN 'Reactivate supplier in Supplier master (SUP_STATUS = A) or assign alternate supplier'         WHEN isc.SUPPLIER IS NULL             THEN 'Create Item/Supplier/Country relationship in ITEM_SUPP_COUNTRY for this item'         WHEN NVL(isc.PRIMARY_SUPP_IND, 'N') != 'Y'             THEN 'Flag supplier as primary on ITEM_SUPP_COUNTRY (PRIMARY_SUPP_IND = Y)'         WHEN NVL(isc.UNIT_COST, 0) = 0             THEN 'Set unit cost > 0 on ITEM_SUPP_COUNTRY for this supplier/country'         WHEN NVL(isc.SUPP_PACK_SIZE, 0) = 0             THEN 'Set SUPP_PACK_SIZE > 0 on ITEM_SUPP_COUNTRY for this supplier/country'         WHEN isc.ORIGIN_COUNTRY_ID IS NULL             THEN 'Set ORIGIN_COUNTRY_ID on ITEM_SUPP_COUNTRY for this supplier'         ELSE 'Review multiple flags and correct each issue'     END                                                 AS recommended_action  FROM     MFCS_RDS.RDS_WV_REPL_ITEM_LOC              ril      JOIN  MFCS_RDS.RDS_WV_ITEM_LOC             il    ON  ril.ITEM                  = il.ITEM                                                      AND  ril.LOCATION              = il.LOC      JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER          im    ON  ril.ITEM                  = im.ITEM                                                      AND  im.TRAN_LEVEL             = im.ITEM_LEVEL      JOIN  MFCS_RDS.RDS_WV_DEPS                 d     ON  im.DEPT                   = d.DEPT     JOIN  MFCS_RDS.RDS_WV_CLASS                c     ON  im.DEPT                   = c.DEPT                                                      AND  im.CLASS                  = c.CLASS     JOIN  MFCS_RDS.RDS_WV_SUBCLASS             sc    ON  im.DEPT                   = sc.DEPT                                                      AND  im.CLASS                  = sc.CLASS                                                      AND  im.SUBCLASS               = sc.SUBCLASS      LEFT JOIN MFCS_RDS.RDS_WV_SUPS             sp    ON  ril.PRIMARY_REPL_SUPPLIER = sp.SUPPLIER      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY isc  ON  ril.ITEM                  = isc.ITEM                                                      AND  ril.PRIMARY_REPL_SUPPLIER = isc.SUPPLIER                                                      AND  isc.PRIMARY_SUPP_IND      = 'Y'                                                      AND  isc.PRIMARY_COUNTRY_IND   = 'Y'      LEFT JOIN MFCS_RDS.RDS_WV_STORE            st    ON  ril.LOCATION              = st.STORE                                                      AND  il.LOC_TYPE               = 'S'      LEFT JOIN MFCS_RDS.RDS_WV_WH              wh     ON  ril.LOCATION              = wh.WH                                                      AND  il.LOC_TYPE               = 'W'  WHERE     ril.REPL_METHOD         IS NOT NULL     AND il.STATUS           IN ('A', 'C')     AND im.STATUS            = 'A'     AND ril.STOCK_CAT       IN ('C', 'D', 'L', 'W')     AND (         ril.PRIMARY_REPL_SUPPLIER IS NULL         OR sp.SUPPLIER IS NULL         OR NVL(sp.SUP_STATUS, 'X') != 'A'         OR isc.SUPPLIER IS NULL         OR NVL(isc.PRIMARY_SUPP_IND, 'N') != 'Y'         OR NVL(isc.UNIT_COST, 0) = 0         OR NVL(isc.SUPP_PACK_SIZE, 0) = 0         OR isc.ORIGIN_COUNTRY_ID IS NULL     )  ORDER BY     primary_issue,     sp.SUP_NAME,     im.DEPT,     im.ITEM_DESC,     ril.LOCATION